"""Exploratory pass: walk /orders page by page, stop at the first non-200 and show it raw."""
import json
import sys
import urllib.error
import urllib.request

BASE = "http://localhost:8080"


def call(method, path, token=None):
    req = urllib.request.Request(
        BASE + path, method=method, data=b"" if method == "POST" else None
    )
    if token:
        req.add_header("Authorization", "Bearer " + token)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, dict(r.headers), r.read()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read()


def main():
    status, _, body = call("POST", "/token")
    token = json.loads(body)["token"]
    print("token:", token)
    for page in range(1, 31):
        status, headers, body = call("GET", f"/orders?page={page}", token)
        if status != 200:
            print(f"page {page}: HTTP {status}")
            print("headers:", json.dumps(headers, indent=1))
            print("body:", body[:1000].decode("utf-8", "replace"))
            return
        doc = json.loads(body)
        print(f"page {page}: ok, {len(doc['items'])} items, next={doc['next']}")


main()

