"""Fetch raw API data to disk.

Usage:
  python3 -I fetch.py orders    DATA_DIR
  python3 -I fetch.py customers DATA_DIR IDS_FILE   (IDS_FILE: one customer id per line)

Every non-200 response is appended to DATA_DIR/events.jsonl so the behaviour of the
service (rate limits, token expiry, errors) can be reviewed afterwards.
"""
import http.client
import json
import os
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime

BASE = "http://localhost:8080"
PAGE_SIZE = 50


class Fatal(Exception):
    pass


def retry_after_seconds(headers, body):
    """Wait time the service asked for: the larger of the header and the body field."""
    found = []
    lowered = {k.lower(): v for k, v in headers.items()}
    value = lowered.get("retry-after")
    if value is not None:
        try:
            found.append(float(value))
        except ValueError:
            try:
                when = parsedate_to_datetime(value)
                found.append(max(0.0, (when - datetime.now(timezone.utc)).total_seconds()))
            except (TypeError, ValueError):
                pass
    try:
        doc = json.loads(body)
        if isinstance(doc, dict) and "retry_after" in doc:
            found.append(float(doc["retry_after"]))
    except (ValueError, TypeError):
        pass
    return max(found) if found else 1.0


class Client:
    def __init__(self, events_path):
        self.token = None
        self.events = open(events_path, "a", buffering=1)
        self.tokens_issued = 0

    def log(self, **fields):
        fields["at"] = time.strftime("%H:%M:%S")
        self.events.write(json.dumps(fields) + "\n")

    def _raw(self, method, path, auth):
        req = urllib.request.Request(
            BASE + path, method=method, data=b"" if method == "POST" else None
        )
        if auth and self.token:
            req.add_header("Authorization", "Bearer " + self.token)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, dict(resp.headers), resp.read()
        except urllib.error.HTTPError as err:
            return err.code, dict(err.headers), err.read()
        except (urllib.error.URLError, TimeoutError, ConnectionError, http.client.HTTPException) as err:
            return None, {}, repr(err).encode()

    def refresh_token(self):
        doc, _ = self.request("POST", "/token", auth=False)
        self.token = doc["token"]
        self.tokens_issued += 1
        self.log(event="new_token", token=self.token)

    def request(self, method, path, auth=True, allow_404=False):
        """Repeat until the request succeeds. Returns (json_doc, raw_body) or (None, raw) on an allowed 404."""
        rate_waits = 0
        auth_failures = 0
        server_errors = 0
        while True:
            if auth and self.token is None:
                self.refresh_token()
            status, headers, body = self._raw(method, path, auth)
            if status == 200:
                try:
                    return json.loads(body), body
                except ValueError:
                    self.log(path=path, status=status, problem="200 but body is not JSON", body=body[:300].decode("utf-8", "replace"))
                    server_errors += 1
            else:
                self.log(path=path, status=status, retry_after=headers.get("Retry-After"),
                         body=body[:300].decode("utf-8", "replace"))
