                    return None, body
                if status is None or status >= 500:
                    server_errors += 1
                else:
                    raise Fatal(f"{path}: unexpected HTTP {status}: {body[:300]!r}")
            if server_errors > 12:
                raise Fatal(f"{path}: failed {server_errors} times")
            time.sleep(min(1.0 * server_errors, 8.0))


