    os.makedirs(pages_dir, exist_ok=True)
    client = Client(os.path.join(data_dir, "events.jsonl"))
    path = "/orders?page=1"
    expected = 1
    total_pages = None
    while path:
        doc, raw = client.request("GET", path)
        if not isinstance(doc, dict) or not {"page", "total_pages", "items", "next"} <= set(doc):
            raise Fatal(f"{path}: 200 response with unexpected shape: {raw[:300]!r}")
        if doc["page"] != expected:
            raise Fatal(f"{path}: asked for page {expected}, service says page {doc['page']}")
