    os.makedirs(cust_dir, exist_ok=True)
    client = Client(os.path.join(data_dir, "events.jsonl"))
    with open(ids_file) as fh:
        ids = [line.strip() for line in fh if line.strip()]
    for i, cid in enumerate(ids, 1):
